&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;We are looking for a passionate and innovative Digital Learning &amp;amp; AI Specialist to help shape the future of learning at Cambridge Consultants.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;469777462&amp;quot;:[1250],&amp;quot;469777927&amp;quot;:[0],&amp;quot;469777928&amp;quot;:[1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
